import numpy as np

def coefs_8ptF_radial_1s(data):

    d = data[0].T.flat

    C = np.zeros((2,16))
    C.flat[24] = d[2]
    C.flat[28] = d[10]
    C.flat[29] = -d[23]
    C.flat[31] = -d[31]
    C.flat[27] = d[18]-d[7]
    C.flat[30] = d[26]-d[15]
    C.flat[0] = d[2]*d[3]*d[6]-d[2]*d[4]*d[5]
    C.flat[9] = d[10]*d[11]*d[14]-d[10]*d[12]*d[13]
    C.flat[6] = d[18]*d[19]*d[22]-d[18]*d[20]*d[21]-d[16]*d[22]+d[17]*d[21]
    C.flat[15] = d[26]*d[27]*d[30]-d[26]*d[28]*d[29]+d[24]*d[28]-d[25]*d[27]
    C.flat[5] = d[2]*d[11]*d[14]-d[2]*d[12]*d[13]+d[3]*d[10]*d[14]-d[4]*d[10]*d[13]-d[5]*d[10]*d[12]+d[6]*d[10]*d[11]
    C.flat[2] = d[2]*d[3]*d[14]-d[2]*d[4]*d[13]-d[2]*d[5]*d[12]+d[2]*d[6]*d[11]+d[3]*d[6]*d[10]-d[4]*d[5]*d[10]
    C.flat[1] = d[2]*d[3]*d[22]-d[2]*d[4]*d[21]-d[2]*d[5]*d[20]+d[2]*d[6]*d[19]+d[3]*d[6]*d[18]-d[4]*d[5]*d[18]-d[0]*d[6]+d[1]*d[5]
    C.flat[12] = d[10]*d[11]*d[30]-d[10]*d[12]*d[29]-d[10]*d[13]*d[28]+d[10]*d[14]*d[27]+d[11]*d[14]*d[26]-d[12]*d[13]*d[26]+d[8]*d[12]-d[9]*d[11]
    C.flat[3] = d[2]*d[19]*d[22]-d[2]*d[20]*d[21]+d[3]*d[18]*d[22]-d[4]*d[18]*d[21]-d[5]*d[18]*d[20]+d[6]*d[18]*d[19]-d[0]*d[22]+d[1]*d[21]+d[5]*d[17]-d[6]*d[16]
    C.flat[14] = d[10]*d[27]*d[30]-d[10]*d[28]*d[29]+d[11]*d[26]*d[30]-d[12]*d[26]*d[29]-d[13]*d[26]*d[28]+d[14]*d[26]*d[27]+d[8]*d[28]-d[9]*d[27]-d[11]*d[25]+d[12]*d[24]
    C.flat[13] = d[18]*d[27]*d[30]-d[18]*d[28]*d[29]+d[19]*d[26]*d[30]-d[20]*d[26]*d[29]-d[21]*d[26]*d[28]+d[22]*d[26]*d[27]+d[16]*d[28]-d[17]*d[27]-d[19]*d[25]+d[20]*d[24]-d[24]*d[30]+d[25]*d[29]
    C.flat[10] = d[18]*d[19]*d[30]-d[18]*d[20]*d[29]-d[18]*d[21]*d[28]+d[18]*d[22]*d[27]+d[19]*d[22]*d[26]-d[20]*d[21]*d[26]+d[16]*d[20]-d[16]*d[30]-d[17]*d[19]+d[17]*d[29]+d[21]*d[25]-d[22]*d[24]
    C.flat[8] = d[2]*d[11]*d[30]-d[2]*d[12]*d[29]-d[2]*d[13]*d[28]+d[2]*d[14]*d[27]+d[3]*d[10]*d[30]+d[3]*d[14]*d[26]-d[4]*d[10]*d[29]-d[4]*d[13]*d[26]-d[5]*d[10]*d[28]-d[5]*d[12]*d[26]+d[6]*d[10]*d[27]+d[6]*d[11]*d[26]+d[10]*d[11]*d[22]-d[10]*d[12]*d[21]-d[10]*d[13]*d[20]+d[10]*d[14]*d[19]+d[11]*d[14]*d[18]-d[12]*d[13]*d[18]+d[0]*d[12]-d[1]*d[11]-d[3]*d[9]+d[4]*d[8]-d[8]*d[14]+d[9]*d[13]
    C.flat[4] = d[2]*d[3]*d[30]-d[2]*d[4]*d[29]-d[2]*d[5]*d[28]+d[2]*d[6]*d[27]+d[2]*d[11]*d[22]-d[2]*d[12]*d[21]-d[2]*d[13]*d[20]+d[2]*d[14]*d[19]+d[3]*d[6]*d[26]+d[3]*d[10]*d[22]+d[3]*d[14]*d[18]-d[4]*d[5]*d[26]-d[4]*d[10]*d[21]-d[4]*d[13]*d[18]-d[5]*d[10]*d[20]-d[5]*d[12]*d[18]+d[6]*d[10]*d[19]+d[6]*d[11]*d[18]+d[0]*d[4]-d[0]*d[14]-d[1]*d[3]+d[1]*d[13]+d[5]*d[9]-d[6]*d[8]
    C.flat[11] = d[2]*d[27]*d[30]-d[2]*d[28]*d[29]+d[3]*d[26]*d[30]-d[4]*d[26]*d[29]-d[5]*d[26]*d[28]+d[6]*d[26]*d[27]+d[10]*d[19]*d[30]-d[10]*d[20]*d[29]-d[10]*d[21]*d[28]+d[10]*d[22]*d[27]+d[11]*d[18]*d[30]+d[11]*d[22]*d[26]-d[12]*d[18]*d[29]-d[12]*d[21]*d[26]-d[13]*d[18]*d[28]-d[13]*d[20]*d[26]+d[14]*d[18]*d[27]+d[14]*d[19]*d[26]+d[0]*d[28]-d[1]*d[27]-d[3]*d[25]+d[4]*d[24]+d[8]*d[20]-d[8]*d[30]-d[9]*d[19]+d[9]*d[29]-d[11]*d[17]+d[12]*d[16]+d[13]*d[25]-d[14]*d[24]
    C.flat[7] = d[2]*d[19]*d[30]-d[2]*d[20]*d[29]-d[2]*d[21]*d[28]+d[2]*d[22]*d[27]+d[3]*d[18]*d[30]+d[3]*d[22]*d[26]-d[4]*d[18]*d[29]-d[4]*d[21]*d[26]-d[5]*d[18]*d[28]-d[5]*d[20]*d[26]+d[6]*d[18]*d[27]+d[6]*d[19]*d[26]+d[10]*d[19]*d[22]-d[10]*d[20]*d[21]+d[11]*d[18]*d[22]-d[12]*d[18]*d[21]-d[13]*d[18]*d[20]+d[14]*d[18]*d[19]+d[0]*d[20]-d[0]*d[30]-d[1]*d[19]+d[1]*d[29]-d[3]*d[17]+d[4]*d[16]+d[5]*d[25]-d[6]*d[24]-d[8]*d[22]+d[9]*d[21]+d[13]*d[17]-d[14]*d[16]

    C = C/np.linalg.norm(C,axis=1,keepdims=True)

    def U(s):
        return np.array([s[1]**3*s[0]**3,s[1]**2*s[0]**3,s[1]**3*s[0]**2,s[1]*s[0]**3,s[1]**2*s[0]**2,s[1]**3*s[0],s[0]**3,s[0]**2*s[1],s[1]**2*s[0],s[1]**3,s[0]**2,s[1]*s[0],s[1]**2,s[0],s[1],1])

    def dU(s):
        return np.column_stack([[3*s[1]**3*s[0]**2,3*s[1]**2*s[0]**2,2*s[1]**3*s[0],3*s[0]**2*s[1],2*s[1]**2*s[0],s[1]**3,3*s[0]**2,2*s[1]*s[0],s[1]**2,0,2*s[0],s[1],0,1,0,0],[3*s[1]**2*s[0]**3,2*s[1]*s[0]**3,3*s[1]**2*s[0]**2,s[0]**3,2*s[0]**2*s[1],3*s[1]**2*s[0],0,s[0]**2,2*s[1]*s[0],3*s[1]**2,0,s[0],2*s[1],0,1,0]])

    return C,U,dU